from add_resume_findings import F,add,render,R
import json
F[31]['severity']='P1'
F[31]['title']='XCOPY targeting D: overwrites files on A:'
F[31]['steps'] += r' For the overwrite repeat, run resume_driver.py xcopyoverwrite: MD A:\DHOME; ECHO KEEP-A > A:\DHOME\ONE.TXT; repeat XCOPY A:\T\ONE.TXT D:\DHOME\ /V.'
F[31]['observed'] += ' In the repeat, the unrelated A: sentinel changes from KEEP-A to ALPHA while no requested D: copy appears.'
F[31]['evidence'] += ['shots/resume-xcopyoverwrite-overwritten.png','evidence/resume-xcopyoverwrite-serial.log','evidence/resume-final-verification.json']
F[16]['title']='FIND returns incorrect status for no match and malformed arguments'
F[16]['steps'] += ' Also run FIND bad < ONE.TXT; IF ERRORLEVEL 2 ECHO BAD-ARGS-RC2; IF NOT ERRORLEVEL 2 ECHO BAD-ARGS-LOW.'
F[16]['observed'] += ' The malformed form prints Invalid number of parameters but BAD-ARGS-LOW, not BAD-ARGS-RC2.'
F[16]['evidence'] += ['shots/resume-external-filters.png','evidence/resume-external-serial.log']
add('Keyboard template','P2','F3 recalls the line that Ctrl-C cancelled','Run resume_driver.py keyboard. ECHO TEMPLATE; then type ECHO CANCELED without Enter. Press Ctrl-C, then F3, Enter.', 'F3 restores ECHO CANCELED and executes it, replacing the preceding completed template.', 'Discard the cancelled line and keep the last completed command as the template. InitechDOS User\'s Guide ch8-keys.tex:25 says "The completed line becomes the template"; lines 32-33 say InitechDOS "discards" the cancelled line. The earlier completed template is ECHO XEMPLATE in the full replay.', 'shots/resume-keyboard-cancel-template.png evidence/resume-keyboard-serial.log evidence/resume_driver.py')
add('MORE display','P3','MORE pauses without displaying --More--',r'Run resume_driver.py external. MORE < PAGES.TXT; wait; press Enter; wait; press Ctrl-C. PAGES.TXT has 65 numbered CR/LF lines.', 'The first pause is after PAGE LINE 023, the second after 047. Both are silent, with no --More-- indicator. The serial byte count stays fixed while paused. Ctrl-C returns to the shell.', 'Show --More-- at a page break (DOS Reference p.20/PDF105 explicitly describes the bottom-of-screen indicator).', 'shots/resume-external-more-page1.png shots/resume-external-more-page2.png evidence/resume-external-serial.log evidence/resume-fixtures/PAGES.TXT evidence/resume-manual-page-105.txt')
add('Native program launch','P1','The shipped 123.EXE and WORD.EXE cannot run from DOS',r'Run resume_driver.py app123 and appword in separate sessions. CD \APPS; DIR 123.EXE; 123.EXE; A:\APPS\123.EXE. Repeat with WORD.EXE.', 'Both present native InitechMZ files are rejected with Bad command or file name. DIR and stopped-image extraction prove the files exist (64892 and 52472 bytes). The prompt survives. SAMIR.COM, the 65536-byte native COM and the small exit programs run.', 'Run the shipped applications from their explicit DOS paths, or give an accurate unsupported/memory diagnostic (the brief\'s Programs test and tester workstation expectation). This concerns the supplied native applications, separately from the foreign 16-bit MZ refusal in L030.', 'shots/resume-app123-qualified.png shots/resume-appword-qualified.png evidence/resume-app123-serial.log evidence/resume-appword-serial.log evidence/recovery-extra-verification.json evidence/appsamir-serial.log')
add('FORMAT system install','P2','FORMAT /S cannot transfer the system from the supplied boot volume',r'Run resume_driver.py format: FORMAT D: /S; DIR D:\. The boot volume C: is the supplied tracer image partition, with IO.SYS and INITDOS.SYS.', 'FORMAT immediately reports Insufficient memory for system transfer. The D: contents remain intact. The source C: root has no COMMAND.COM file. Ordinary FORMAT D: followed by SYS D: succeeds when the target root entries are free.', 'Provide a usable shipped /S installation path or accurately identify the missing source file. InitechDOS Reference ch2-entries-b.tex:207-209 promises that /S "copies the system files and COMMAND.COM from drive C" and the result can start the system. Missing COMMAND.COM is a suspected cause, not a proven exclusive cause.', 'shots/resume-format-system-before.png evidence/resume-format-serial.log evidence/advanced-format-C-listing.txt evidence/resume-format-verification.json')
add('Filesystem after disk utilities','P1','A write after FORMAT and SYS corrupts the transferred system files',r'Run resume_driver.py syswrite. FORMAT D:; answer EXTRA, Y. SYS D:; DIR D:\; ECHO NEW-DATA > D:\NEW.TXT; TYPE D:\NEW.TXT; DIR D:\. Stop QEMU and extract D: from byte 2097152 of resume-syswrite-boot.img.', 'SYS reports System transferred. DIR lists IO.SYS=1647 and INITDOS.SYS=196608 but claims 1456640 bytes free, already wrong. After the ten-byte NEW.TXT write, mcopy can recover only 512 bytes of IO.SYS; INITDOS.SYS cannot be read. fsck.fat -n reports a free cluster in INITDOS.SYS and shortened chains. A separate control stopped after SYS has both files byte-identical to the original C: files and 1259008 bytes free. No error is shown by the guest.', 'Keep filesystem allocation state coherent after raw disk utilities; later ordinary writes must preserve the installed system files (tester filesystem correctness expectation; InitechDOS SYS contract ch2-entries-c.tex:74-77). Stale mounted FAT state is a root-cause guess; corruption is established by the extracted bytes and independent checker.', 'shots/resume-syswrite-after-write.png evidence/resume-syswrite-serial.log evidence/resume-syswrite-verification.json evidence/resume-syswrite-fsck.txt evidence/resume-syswrite-IO.SYS evidence/resume-syswrite-INITDOS.SYS evidence/resume-format-verification.json evidence/resume-format-D-IO.SYS evidence/resume-format-D-INITDOS.SYS evidence/resume_driver.py')
add('DIR cancellation','P2','Ctrl-C advances DIR /P instead of cancelling the listing',r'Run resume_driver.py gaps2. DIR \MANY /P; at the first Press any key to continue prompt, press Ctrl-C. Continue with Space until all 300 files are listed.', 'Ctrl-C advances to the next page and another pause. The listing runs through F299.TXT. A final Ctrl-C at the shell only clears surplus queued spaces.', 'Abort the active command on Ctrl-C (DOS editing-keys Reference p.159/PDF244; tester DIR expectation).', 'shots/resume-gaps2-dir-break.png shots/resume-gaps2-dir-returned.png evidence/resume-gaps2-serial.log evidence/manual-page-244.txt')
add('SORT arguments','P3','SORT silently accepts an unknown switch','Run resume_driver.py external: SORT /BAD < LINES.TXT; IF NOT ERRORLEVEL 1 ECHO SORT-RC0.', 'It sorts normally and prints SORT-RC0; no invalid-switch diagnostic appears.', 'Reject unknown switches so mistyped options are visible (tester diagnostic expectation; DOS Reference p.116 lists /R and /+n).', 'shots/resume-external-filters.png evidence/resume-external-serial.log evidence/manual-page-201.txt')
add('Batch expansion','P2','An undefined batch environment variable is left as literal text','Run resume_driver.py keyboard on a fresh fixture where TEST is unset; run BENV.BAT, which contains ECHO VALUE=%TEST%. As a control, resume_driver.py batch sets TEST=VALUE first.', 'The unset case prints VALUE=%TEST%; the defined case prints VALUE=VALUE.', 'Expand an undefined environment variable to the empty string (tester DOS batch-expansion memory). Preserve the ordinary literal-percent escape %% separately, which passes here.', 'shots/resume-keyboard-recall-kinds.png shots/resume-batch-flow.png evidence/resume-keyboard-serial.log evidence/resume-batch-serial.log evidence/resume-fixtures/BENV.BAT')
add('BREAK arguments','P3','BREAK INVALID is treated as a state query','Run resume_driver.py gaps2: BREAK OFF; BREAK; BREAK ON; BREAK; BREAK INVALID.', 'Valid ON/OFF forms work. INVALID produces BREAK is on rather than an argument error.', 'Reject unsupported settings (tester command-diagnostic expectation; DOS BREAK syntax allows ON/OFF or no operand).', 'shots/resume-gaps2-builtins.png evidence/resume-gaps2-serial.log evidence/suite3-B042.txt')
add('PROMPT compatibility','P2','PROMPT $V prints V instead of the DOS version','Run resume_driver.py promptversion; type PROMPT $V$G.', 'The prompt becomes V>, rather than showing the version number.', 'Expand $V to the version number (original DOS Reference printed p.101/PDF186, Special prompts table). The shipped Initech prompt table omits this DOS code, so this is compatibility.', 'shots/resume-promptversion-version.png evidence/resume-promptversion-serial.log evidence/manual-page-186.txt')

# Expand manual names to unambiguous repository-relative paths.
for finding in F:
 for key in ['expected']:
  finding[key]=finding[key].replace('InitechDOS Reference ch','pubs/manuals/initechdos-reference/ch').replace("InitechDOS User's Guide ch",'pubs/manuals/initechdos-users-guide/ch')
F[4]['expected'] += ' Exact contract, pubs/manuals/initechdos-reference/ch4-batch.tex:20-21: "InitechDOS carries out the commands in it one after another".'
F[7]['expected'] += ' Exact wording, pubs/manuals/initechdos-reference/ch4-batch.tex:32: "type its name without the extension".'
F[8]['expected'] += ' Exact wording, pubs/manuals/initechdos-reference/ch2-entries-b.tex:102-104: "so that you can type commands without leaving the program".'
F[11]['expected'] += ' The filename syntax at pubs/manuals/initechdos-reference/ch2-entries-a.tex:11 explicitly begins with optional d: and path; line 26 says "names the files to change or display".'
F[13]['expected'] += ' The TREE syntax at pubs/manuals/initechdos-reference/ch2-entries-c.tex:127-128 includes a drive-qualified path; line 131 says "names the directory to start from".'
F[31]['expected'] += ' Exact target contract, pubs/manuals/initechdos-reference/ch2-entries-c.tex:225: "The second names the target."'

if __name__=='__main__':
 (R/'evidence/final-findings.json').write_text(json.dumps(F,indent=2))
 tail=(R/'evidence/report-tail.txt').read_text() if (R/'evidence/report-tail.txt').exists() else 'Final verification in progress.\n'
